import express from "express";
import bcrypt from "bcryptjs";
import Membership from "../models/Membership.js";

const router = express.Router();

// ✅ Register new member
router.post("/", async (req, res) => {
  try {
    const { name, email, password, payment, gcashNumber } = req.body;

    // Check if email already exists
    const existing = await Membership.findOne({ email });
    if (existing) return res.status(400).json({ message: "Email already registered." });

    // Hash password
    const hashedPassword = await bcrypt.hash(password || "123456", 10);

    const newMember = new Membership({
      name,
      email,
      password: hashedPassword,
      payment,
      gcashNumber,
      remainingHours: 10, // Default starting hours
    });

    await newMember.save();
    res.status(201).json({ message: "Membership created successfully!" });
  } catch (error) {
    console.error("Error creating membership:", error);
    res.status(500).json({ message: "Server error" });
  }
});

// ✅ Login route
router.post("/login", async (req, res) => {
  try {
    const { email, password } = req.body;

    // Check if user exists
    const member = await Membership.findOne({ email });
    if (!member) return res.status(404).json({ message: "No account found" });

    // Compare password
    const isMatch = await bcrypt.compare(password, member.password);
    if (!isMatch) return res.status(401).json({ message: "Invalid credentials" });

    // Success
    res.status(200).json({
      name: member.name,
      email: member.email,
      remainingHours: member.remainingHours,
    });
  } catch (error) {
    console.error("Login error:", error);
    res.status(500).json({ message: "Server error" });
  }
});

// ✅ Get all members (for admin/debug)
router.get("/", async (req, res) => {
  try {
    const members = await Membership.find();
    res.status(200).json(members);
  } catch (error) {
    res.status(500).json({ message: "Server error" });
  }
});

export default router;
